    {"id": 3, "email": "c@example.com", "name": "C", "session": "general", "workshop_id": 7, "status": "waitlist"},
    {"id": 4, "email": "d@example.com", "name": "D", "session": "general", "workshop_id": 7, "status": "confirmed"},
