def test_task01_post_signups_creates_one_and_hides_the_email(client, repo):
    response = client.post(
        "/signups", json={"email": "e@example.com", "name": "E", "session": "data", "workshop_id": 9}
    )
    assert response.status_code == 201, (
        f"Task 1: POST /signups must answer 201, got {response.status_code}; "
        "add @app.post(\"/signups\", status_code=201, response_model=SignupOut)"
    )
    assert response.json() == {"id": 5, "name": "E", "session": "data", "status": "confirmed", "workshop_id": 9}, (
        "Task 1: answer with the created sign-up through SignupOut (id, name, session, status, workshop_id; no email)"
    )
    assert repo.get(5)["email"] == "e@example.com", "Task 1: store the new sign-up with repo.add(...)"
    bad = client.post("/signups", json={"email": "f@example.com", "name": "F", "session": "data", "workshop_id": "x"})
    assert bad.status_code == 422 and bad.json()["detail"][0]["loc"] == ["body", "workshop_id"], (
        "Task 1: type the body with SignupIn so a non-integer workshop_id is rejected with 422"
    )


def test_task02_get_one_signup_or_404(client):
    response = client.get("/signups/3")
    assert response.status_code == 200, (
        f"Task 2: GET /signups/3 must answer 200, got {response.status_code}; "
        "add @app.get(\"/signups/{signup_id}\", response_model=SignupOut)"
    )
    assert response.json() == {"id": 3, "name": "C", "session": "general", "status": "waitlist", "workshop_id": 7}, (
        "Task 2: declare response_model=SignupOut so the email is left out"
    )
    missing = client.get("/signups/99")
    assert missing.status_code == 404 and missing.json() == {"detail": "Sign-up not found"}, (
        "Task 2: raise HTTPException(status_code=404, detail=\"Sign-up not found\") for an unknown id"
    )
    assert client.get("/signups/abc").status_code == 422, "Task 2: declare signup_id: int"


def test_task03_session_listing_pages_with_limit_and_offset(client):
    page = client.get("/sessions/general/signups", params={"limit": 2, "offset": 1})
    assert page.status_code == 200, (
        f"Task 3: the listing must answer 200, got {page.status_code}; "
        "add @app.get(\"/sessions/{session}/signups\", response_model=list[SignupOut])"
    )
    assert [s["id"] for s in page.json()] == [3, 4], "Task 3: limit=2&offset=1 skips one sign-up and returns two"
    assert all("email" not in s for s in page.json()), "Task 3: declare response_model=list[SignupOut]"
    default = client.get("/sessions/general/signups")
    assert [s["id"] for s in default.json()] == [1, 3, 4], "Task 3: the defaults are limit=10 and offset=0"
    for params in ({"limit": 0}, {"limit": 51}, {"offset": -1}, {"limit": "abc"}):
        assert client.get("/sessions/general/signups", params=params).status_code == 422, (
            f"Task 3: {params} must be rejected with 422 (Query(10, ge=1, le=50) and Query(0, ge=0))"
        )


def test_task04_settings_come_from_environment_variables(spring_env, monkeypatch):
    loaded = settings.Settings()
    assert getattr(loaded, "spring_base_url", None) == SPRING, "Task 4: declare spring_base_url: str"
    assert getattr(loaded, "spring_token", None) == "lab-token", "Task 4: declare spring_token: str"
    assert getattr(loaded, "spring_timeout_seconds", None) == 2.0, "Task 4: spring_timeout_seconds: float = 2.0"
    monkeypatch.setenv("SPRING_TIMEOUT_SECONDS", "0.5")
    assert settings.Settings().spring_timeout_seconds == 0.5, "Task 4: SPRING_TIMEOUT_SECONDS sets the timeout"
    monkeypatch.delenv("SPRING_TOKEN")
    try:
        settings.Settings(_env_file=None)
    except Exception as err:
        assert type(err).__name__ == "ValidationError", f"Task 4: a missing token must raise ValidationError, got {err!r}"
    else:
        pytest.fail("Task 4: the token is required: declare spring_token: str with no default")


def test_task05_client_sends_the_token_to_the_base_url_with_a_timeout(monkeypatch):
    def no_network(self, request):
        pytest.fail("Task 5: pass transport=transport to httpx.Client (the check must not reach the network)")

    monkeypatch.setattr(httpx.HTTPTransport, "handle_request", no_network)
    seen = []

    def handler(request):
        seen.append(request)
        return httpx.Response(200, json=WORKSHOP)

    config = SimpleNamespace(spring_base_url=SPRING, spring_token="lab-token", spring_timeout_seconds=1.5)
    with upstream.make_client(config, transport=httpx.MockTransport(handler)) as http:
        assert isinstance(http, httpx.Client), "Task 5: return an httpx.Client"
        assert http.timeout.read == 1.5 and http.timeout.connect == 1.5, (
            "Task 5: pass timeout=httpx.Timeout(settings.spring_timeout_seconds)"
        )
        http.get("/workshops/7")
    assert seen, "Task 5: pass transport=transport to httpx.Client"
    assert str(seen[0].url) == f"{SPRING}/workshops/7", "Task 5: set base_url from settings.spring_base_url"
    assert seen[0].headers.get("Authorization") == "Bearer lab-token", (
        "Task 5: send the header Authorization: Bearer <spring_token>"
    )


def mock_client(handler):
    return httpx.Client(base_url=SPRING, transport=httpx.MockTransport(handler))


def test_task06_fetch_workshop_maps_each_upstream_failure():
    def ok(request):
        assert request.url.path == "/workshops/7"
        return httpx.Response(200, json=WORKSHOP)

    assert upstream.fetch_workshop(mock_client(ok), 7) == WORKSHOP, "Task 6: return the JSON body as a dict"

    def slow(request):
        raise httpx.ReadTimeout("slow", request=request)

    def no_connect(request):
        raise httpx.ConnectTimeout("no answer", request=request)

    def down(request):
        raise httpx.ConnectError("refused", request=request)

    cases = [
        (slow, 504, "Workshop service timed out"),
        (no_connect, 504, "Workshop service timed out"),
        (down, 502, "Workshop service unavailable"),
        (lambda request: httpx.Response(500), 502, "Workshop service returned 500"),
        (lambda request: httpx.Response(404), 502, "Workshop service returned 404"),
    ]
    hint = "catch TimeoutException before TransportError, and call raise_for_status() so a non-2xx answer raises"
    for handler, status, detail in cases:
        try:
            upstream.fetch_workshop(mock_client(handler), 7)
        except upstream.UpstreamError as err:
            got = (err.status_code, err.detail)
        except Exception as err:
            pytest.fail(f"Task 6: expected UpstreamError({status}, {detail!r}), but {err!r} escaped; {hint}")
        else:
            pytest.fail(f"Task 6: expected UpstreamError({status}, {detail!r}), but nothing was raised; {hint}")
        assert got == (status, detail), (
            f"Task 6: expected UpstreamError({status}, {detail!r}), got UpstreamError{got!r}; {hint}"
        )


def use_workshop_handler(handler):
    def override():
        with mock_client(handler) as http:
            yield http

    main.app.dependency_overrides[main.get_workshop_client] = override


def workshop_answer(client, path):
    try:
        return client.get(path)
    except upstream.UpstreamError as err:
        pytest.fail(
            f"Task 7: UpstreamError({err.status_code}, {err.detail!r}) escaped the route; catch it and "
            "raise HTTPException(status_code=err.status_code, detail=err.detail)"
        )


def test_task07_workshop_route_turns_upstream_errors_into_responses(client, monkeypatch):
    monkeypatch.delenv("SPRING_BASE_URL", raising=False)
    monkeypatch.delenv("SPRING_TOKEN", raising=False)
    use_workshop_handler(lambda request: httpx.Response(200, json=WORKSHOP))
    response = workshop_answer(client, "/signups/1/workshop")
    assert response.status_code != 404 or response.json() != {"detail": "Not Found"}, (
        "Task 7: GET /signups/1/workshop answered 404 Not Found; add the route with client=Depends(get_workshop_client)"
    )
    assert response.status_code == 200, f"Task 7: GET /signups/1/workshop must answer 200, got {response.status_code}"
    assert response.json() == {"signup_id": 1, "workshop": WORKSHOP}, (
        "Task 7: answer {\"signup_id\": ..., \"workshop\": <the catalog's JSON>}"
    )
    assert workshop_answer(client, "/signups/99/workshop").status_code == 404, "Task 7: an unknown sign-up is a 404"

    def slow(request):
        raise httpx.ReadTimeout("slow", request=request)

    use_workshop_handler(slow)
    timed_out = workshop_answer(client, "/signups/1/workshop")
    assert timed_out.status_code == 504 and timed_out.json() == {"detail": "Workshop service timed out"}, (
        f"Task 7: got {timed_out.status_code}; raise HTTPException with the UpstreamError's status_code and detail"
    )
    use_workshop_handler(lambda request: httpx.Response(500))
    assert workshop_answer(client, "/signups/1/workshop").status_code == 502, "Task 7: a 500 from the catalog is our 502"


MUTANTS = {
    "every route answers 200 with an empty body": (
        "import fastapi\n"
        "bad = fastapi.FastAPI()\n"
        "@bad.api_route('/{path:path}', methods=['GET', 'POST'])\n"
        "def anything(path: str):\n"
        "    return {}\n"
        "m.app = bad\n"
    ),
    "the app ignores dependency overrides": "Recorder.keep = False\n",
    "fetch_workshop never raises": "u.fetch_workshop = m.fetch_workshop = lambda client, workshop_id: {'id': workshop_id}\n",
    "fetch_workshop answers every failure with the wrong status": (
        "def wrong(client, workshop_id):\n"
        "    raise u.UpstreamError(500, 'wrong')\n"
        "u.fetch_workshop = m.fetch_workshop = wrong\n"
    ),
}

RECORDER = (
    "class Recorder(dict):\n"
    "    keep = True\n"
    "    seen = set()\n"
    "    def __setitem__(self, key, value):\n"
    "        Recorder.seen.add(getattr(key, '__name__', repr(key)))\n"
    "        if Recorder.keep:\n"
    "            super().__setitem__(key, value)\n"
    "    def update(self, *args, **kwargs):\n"
    "        for key, value in dict(*args, **kwargs).items():\n"
    "            self[key] = value\n"
    "m.app.dependency_overrides = Recorder()\n"
)


def run_learner_tests(patch=""):
    code = (
        "import json, sys, pytest\n"
        "import signups_api.main as m\n"
        "import signups_api.upstream as u\n"
        f"{RECORDER}{patch}"
        "status = pytest.main(['-q', '-p', 'no:cacheprovider', 'test_api.py'])\n"
        "print('OVERRIDDEN=' + json.dumps(sorted(Recorder.seen)))\n"
        "sys.exit(status)\n"
    )
    env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1")
    return subprocess.run(
        [sys.executable, "-c", code], cwd=STARTER, capture_output=True, text=True, timeout=120, env=env
    )


def overridden(result):
    lines = [line for line in result.stdout.splitlines() if line.startswith("OVERRIDDEN=")]
    return set(json.loads(lines[-1].split("=", 1)[1])) if lines else set()


def test_task08_your_tests_use_testclient_an_override_and_a_mock_transport():
    tree = ast.parse((STARTER / "test_api.py").read_bytes())
    tests = [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef) and n.name.startswith("test_")]
    assert len(tests) >= 2, "Task 8: add at least two test functions to starter/test_api.py"
    calls = [ast.unparse(n.func) for n in ast.walk(tree) if isinstance(n, ast.Call)]
    assert any(c.endswith("MockTransport") for c in calls), "Task 8: test the outbound call with an httpx.MockTransport"
    clean = run_learner_tests()
    assert clean.returncode == 0, "Task 8: your tests must pass against your code:\n" + clean.stdout[-1500:]
    assert "get_repository" in overridden(clean), (
        "Task 8: in a test, replace the repository with app.dependency_overrides[get_repository] = ..."
    )
    for bug, patch in MUTANTS.items():
        result = run_learner_tests(patch)
        assert result.returncode != 0, f"Task 8: your tests still pass when {bug}; add a test that catches it"
